using System;
using System.IO;
using System.Threading.Tasks;
using System.Diagnostics;
using System.Text.RegularExpressions;
using Grpc.Core;
using Google.Protobuf;

namespace FileProcessingService
{
    public class FileUploadService : FileProcessor.FileProcessorBase
    {
        private static readonly string WorkDir = "/var/processing/uploads";
        private static readonly Regex SafeFilenamePattern = new Regex(@"^[a-zA-Z0-9_\-]+\.[a-zA-Z0-9]+$", RegexOptions.Compiled);

        public override async Task<ProcessingResponse> ProcessUpload(
            UploadRequest request, ServerCallContext context)
        {
            var metadata = ParseMetadata(request.Metadata);
            var fileBytes = request.FileContent.ToByteArray();

            // Validate filename from metadata
            string originalFilename = metadata.GetValueOrDefault("filename", "unknown.bin");
            if (!SafeFilenamePattern.IsMatch(originalFilename))
            {
                return new ProcessingResponse { Success = false, Message = "Invalid filename" };
            }

            // Generate safe internal path
            string sessionId = GenerateSessionId(context);
            string safeDir = Path.Combine(WorkDir, sessionId);
            Directory.CreateDirectory(safeDir);

            string filePath = Path.Combine(safeDir, originalFilename);
            await File.WriteAllBytesAsync(filePath, fileBytes);

            // Determine processing pipeline based on content type
            string contentType = metadata.GetValueOrDefault("content-type", "application/octet-stream");
            var result = await RunProcessingPipeline(filePath, contentType, metadata);

            return new ProcessingResponse { Success = result.ExitCode == 0, Message = result.Output };
        }

        private async Task<PipelineResult> RunProcessingPipeline(
            string filePath, string contentType, Dictionary<string, string> metadata)
        {
            string tool = ResolveProcessingTool(contentType);
            string[] arguments = BuildArgumentArray(filePath, tool, metadata);

            return await ExecuteSecurely(tool, arguments);
        }

        private string ResolveProcessingTool(string contentType)
        {
            return contentType switch
            {
                "image/png" => "/usr/bin/pngcheck",
                "image/jpeg" => "/usr/bin/jpeginfo",
                "application/pdf" => "/usr/bin/pdfinfo",
                "video/mp4" => "/usr/bin/ffprobe",
                _ => "/usr/bin/file"
            };
        }

        private string[] BuildArgumentArray(string filePath, string tool, Dictionary<string, string> metadata)
        {
            var args = new List<string>();

            // Some tools support additional processing options
            if (tool == "/usr/bin/ffprobe" && metadata.ContainsKey("probe-options"))
            {
                var probeOpts = SanitizeProbeOptions(metadata["probe-options"]);
                args.AddRange(probeOpts);
            }

            // File path is passed as a discrete argument element - no shell interpretation
            args.Add(filePath);

            return args.ToArray();
        }

        private List<string> SanitizeProbeOptions(string options)
        {
            // Allow only known-safe ffprobe flags
            var allowed = new HashSet<string> { "-show_format", "-show_streams", "-show_packets", "-print_format", "json", "xml", "csv" };
            var parts = options.Split(' ', StringSplitOptions.RemoveEmptyEntries);
            var sanitized = new List<string>();

            foreach (var part in parts)
            {
                if (allowed.Contains(part))
                {
                    sanitized.Add(part);
                }
            }

            return sanitized;
        }

        private async Task<PipelineResult> ExecuteSecurely(string tool, string[] arguments)
        {
            // Validate tool path exists and is in allowed directory
            if (!tool.StartsWith("/usr/bin/") || !File.Exists(tool))
            {
                return new PipelineResult { ExitCode = -1, Output = "Invalid tool" };
            }

            var psi = new ProcessStartInfo
            {
                FileName = tool,
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                UseShellExecute = false,
                CreateNoWindow = true
            };

            // Pass arguments as discrete elements - prevents shell injection
            foreach (var arg in arguments)
            {
                psi.ArgumentList.Add(arg);
            }

            // Apply environment hardening
            psi.Environment["PATH"] = "/usr/bin";
            psi.Environment["LC_ALL"] = "C";

            using var process = Process.Start(psi);
            string output = await process.StandardOutput.ReadToEndAsync();
            string error = await process.StandardError.ReadToEndAsync();
            await process.WaitForExitAsync();

            return new PipelineResult
            {
                ExitCode = process.ExitCode,
                Output = output.Length > 4096 ? output[..4096] : output
            };
        }

        private Dictionary<string, string> ParseMetadata(MapField<string, string> grpcMetadata)
        {
            var dict = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            foreach (var entry in grpcMetadata)
            {
                dict[entry.Key] = entry.Value;
            }
            return dict;
        }

        private string GenerateSessionId(ServerCallContext context)
        {
            var peer = context.Peer ?? "unknown";
            var timestamp = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
            using var sha = System.Security.Cryptography.SHA256.Create();
            var hash = sha.ComputeHash(System.Text.Encoding.UTF8.GetBytes($"{peer}:{timestamp}"));
            return Convert.ToHexString(hash)[..16].ToLowerInvariant();
        }
    }

    public class PipelineResult
    {
        public int ExitCode { get; set; }
        public string Output { get; set; }
    }
}
